import { cloneElement, isValidElement, useId, type ReactNode } from 'react';

export type FieldProps = {
  label?: string;
  description?: string;
  error?: string;
  required?: boolean;
  disabled?: boolean;
  htmlFor?: string;
  children: ReactNode;
  className?: string;
};

function cn(...classes: (string | false | undefined | null)[]) {
  return classes.filter(Boolean).join(' ');
}

export function Field({
  label,
  description,
  error,
  required = false,
  disabled = false,
  htmlFor,
  children,
  className,
}: FieldProps) {
  const id = useId();
  // El error sustituye a la descripcion en el render, asi que solo se referencia
  // el texto que de verdad esta en el DOM: apuntar a un id ausente deja al lector
  // de pantalla sin anunciar nada.
  const descriptionId = description && !error ? `${id}-description` : undefined;
  const errorId = error ? `${id}-error` : undefined;
  const describedBy = [descriptionId, errorId].filter(Boolean).join(' ') || undefined;

  // Solo se anota el control cuando Field recibe un unico elemento: con varios
  // hijos no hay forma de saber cual es el campo, y describir el equivocado es
  // peor que no describir nada.
  const describedChildren =
    describedBy && isValidElement<{ 'aria-describedby'?: string }>(children)
      ? cloneElement(children, {
          'aria-describedby': [children.props['aria-describedby'], describedBy]
            .filter(Boolean)
            .join(' '),
        })
      : children;

  return (
    <div
      className={cn('field', disabled && 'field--disabled', className)}
      role="group"
      {...(error ? { 'data-invalid': '' } : {})}
    >
      {label && (
        <label
          className={cn('field__label', required && 'field__label--required')}
          htmlFor={htmlFor}
        >
          {label}
        </label>
      )}
      {describedChildren}
      {description && !error && (
        <p className="field__description" id={descriptionId}>{description}</p>
      )}
      {error && (
        <p className="field__error" id={errorId} role="alert">{error}</p>
      )}
    </div>
  );
}

/* -------------------------------------------------------------------------
   Field

   Wrapper for form controls: label + input + description + error.
   Composes with Input, Textarea, Select, Checkbox, etc.
   Colors matched to Figma atom-text-field.

   Orientation: vertical (default)
   ------------------------------------------------------------------------- */

.field {
  display: flex;
  flex-direction: column;
  gap: var(--spacing-1);
  width: 100%;
}

.field__label {
  font-family: var(--font-family-sans), ui-sans-serif, system-ui, sans-serif;
  font-size: var(--font-size-xs);
  font-weight: var(--font-weight-medium);
  line-height: 1;
  color: var(--foreground);
}

.field__label--required::after {
  content: " *";
  color: var(--destructive);
}

.field__description {
  margin-top: var(--spacing-1);
  font-family: var(--font-family-sans), ui-sans-serif, system-ui, sans-serif;
  font-size: var(--font-size-xs);
  line-height: 1.4;
  color: var(--placeholder);
}

.field__error {
  margin-top: var(--spacing-1);
  font-family: var(--font-family-sans), ui-sans-serif, system-ui, sans-serif;
  font-size: var(--font-size-xs);
  line-height: 1.4;
  color: var(--destructive);
}

/* Error state — label turns red */
.field[data-invalid] .field__label {
  color: var(--destructive);
}

/* Disabled state — label grays out */
.field--disabled .field__label {
  color: var(--muted-foreground);
}

